"""Concrete test cases produced from a task's test-item definitions."""

from typing import Annotated, Literal

from pydantic import Field

from redteam.core.models.task import DatasetReference, DomainModel, NonEmptyStr


class DatasetCaseSource(DomainModel):
    """A concrete case loaded from a versioned dataset entry."""

    kind: Literal["dataset"] = "dataset"
    dataset: DatasetReference
    source_case_id: NonEmptyStr


class GeneratedCaseSource(DomainModel):
    """A concrete case generated by the task-level attacker model."""

    kind: Literal["generated"] = "generated"


CaseSource = Annotated[
    DatasetCaseSource | GeneratedCaseSource,
    Field(discriminator="kind"),
]


class TestCase(DomainModel):
    """One concrete test case that can be executed and evaluated independently.

    A single-round case produces one step. A multi-round case produces multiple
    steps in the same target conversation. Risk, evaluation, and round limits
    remain defined by the referenced immutable TestItem.
    """

    case_id: NonEmptyStr
    test_item_id: NonEmptyStr
    initial_prompt: NonEmptyStr
    source: CaseSource
